    if mode == "int8":
        return codes.double() - 128.0
    lo = (codes & 0xF).double() - 8.0
    hi = ((codes >> 4) & 0xF).double() - 8.0
    return torch.stack((lo, hi), dim=-1).reshape(codes.shape[0], -1)


