@pytest.mark.parametrize("dtype", DTYPE_LIST)
@pytest.mark.parametrize("has_bias", [False, True])
def test__mixed_dtypes_linear(shape, mode, activation, dtype, has_bias, caplog):
    x, weight, scale, bias = _make_operands(shape, dtype, mode, has_bias)

    ref_out = _reference(x, weight, scale, bias, activation, mode, dtype)

    with caplog.at_level("DEBUG", logger="flag_gems.ops._mixed_dtypes_linear"):
        res_out = flag_gems._mixed_dtypes_linear(
            x, weight, scale, bias=bias, activation=activation
        )

    assert "GEMS _MIXED_DTYPES_LINEAR" in caplog.text
    assert res_out.dtype == dtype
    assert res_out.shape == ref_out.shape
    _assert_close(res_out, ref_out.to(dtype), dtype, reduce_dim=shape[1])


