def test__mixed_dtypes_linear_3d_input(mode, dtype):
    # A 3-D input is flattened to (M, K) with M = numel / K; the leading
    # dimensions are kept in the result.
    K, N = 128, 64
    x = torch.randn((2, 3, K), dtype=dtype, device=flag_gems.device)
    ncols = N if mode == "int8" else N // 2
    weight = torch.randint(0, 256, (K, ncols), dtype=torch.int32).to(torch.uint8)
    weight = weight.to(flag_gems.device)
    scale = torch.rand((N,), dtype=dtype, device=flag_gems.device) * 0.02

    ref_out = _reference(x.reshape(-1, K), weight, scale, None, None, mode, dtype)

    res_out = flag_gems._mixed_dtypes_linear(x, weight, scale)

    assert res_out.shape == (2, 3, N)
    _assert_close(res_out, ref_out.to(dtype).reshape(2, 3, N), dtype, reduce_dim=K)


